from src.nodes.base import BaseNode
from src.runtime.assets.acquisition import get_acquisition_manager
import json

class Hou_Mcp_Asset_Acquisition(BaseNode):
    name = "hou_mcp_asset_acquisition"

    def __init__(self):
        super().__init__()
        # [AUTO-GENERATED-PORTS-START]
        self.add_input("action",    "string", widget_type="text", default="ensure")
        self.add_input("provider",  "string", widget_type="text", default="")
        self.add_input("asset_id",  "string", widget_type="text", default="")
        self.add_input("asset_json","string", widget_type="text", default="")
        self.add_input("local_path","string", widget_type="text", default="")
        # [AUTO-GENERATED-PORTS-END]
        self.add_output("result_json", "string")
        self.add_output("local_path",  "string")
        self.add_output("found",       "bool")

    async def execute(self, inputs):
        action     = str(inputs.get("action",    "ensure") or "ensure").strip().lower()
        provider   = str(inputs.get("provider",  "") or "")
        asset_id   = str(inputs.get("asset_id",  "") or "")
        asset_json = str(inputs.get("asset_json","") or "")
        lpath      = str(inputs.get("local_path","") or "")
        mgr = get_acquisition_manager()
        try:
            if action == "ensure":
                result = mgr.ensure_asset_available(provider, asset_id)
                self.log_info(f"Acquisition ensure: {asset_id!r} — found={result.ok}, source={result.source}")
                return {"result_json": json.dumps(result.to_dict(), sort_keys=True, default=str),
                        "local_path": result.local_path, "found": result.ok, "exec_out": True}
            elif action == "locate":
                path = mgr.locate_asset(provider, asset_id)
                found = path is not None
                self.log_info(f"Acquisition locate: {asset_id!r} — found={found}")
                return {"result_json": json.dumps({"asset_id": asset_id, "local_path": path or "", "found": found}, sort_keys=True),
                        "local_path": path or "", "found": found, "exec_out": True}
            elif action == "request":
                try:
                    asset_dict = json.loads(asset_json) if asset_json.strip() else {}
                except Exception:
                    asset_dict = {"asset_id": asset_id, "provider": provider}
                req = mgr.request_acquisition(asset_dict)
                self.log_info(f"Acquisition request: {asset_id!r} — status={req.status}")
                return {"result_json": json.dumps(req.to_dict(), sort_keys=True, default=str),
                        "local_path": "", "found": False, "exec_out": True}
            elif action == "register":
                try:
                    meta = json.loads(asset_json) if asset_json.strip() else {}
                except Exception:
                    meta = {}
                result = mgr.register_downloaded_asset(lpath, meta)
                self.log_info(f"Acquisition register: {lpath!r} — ok={result.ok}")
                return {"result_json": json.dumps(result.to_dict(), sort_keys=True, default=str),
                        "local_path": result.local_path, "found": result.ok, "exec_out": True}
            else:
                self.log_error(f"Unknown action: {action!r}. Use: ensure, locate, request, register.")
                return {"result_json": "{}", "local_path": "", "found": False, "exec_out": True}
        except Exception as exc:
            self.log_error(f"Asset acquisition failed: {exc}")
            return {"result_json": "{}", "local_path": "", "found": False, "exec_out": True}

def register_node():
    return Hou_Mcp_Asset_Acquisition
